import {mountFeishu} from './feishu.js';
const api=async(path,data)=>{const r=await fetch(path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const j=await r.json();if(!r.ok)throw Error(j.error||'设置服务未响应');return j};
export async function mountSettings(){const host=document.querySelector('#workspaceBody');host.innerHTML=`<div class="settings-intro"><span class="tag">PERSONAL AGENT</span><h2>让 JARVIS 随时与你连接</h2><p>管理研究 Agent、消息通道与通知计划。</p></div><div class="settings-columns"><section class="work-card"><h3>研究 Agent</h3><h2>五简 JARVIS</h2><p class="model-state">正在检查模型…</p><p>国内期货 · 真实行情 · 深度研究</p><span class="tag">只读研究，不自动下单</span></section><section class="work-card"><h3>语音通话</h3><label>默认通道 <select class="voice-provider"><option value="volc">火山实时语音 + DeepSeek</option><option value="gpt">GPT-Live</option><option value="browser">浏览器语音</option></select></label><p class="voice-state">正在检查语音…</p><p>通话与后台研究独立运行，挂断不取消已启动的研究。</p></section></div><section class="work-card im-channel"><div class="im-heading"><div><span class="tag">IM CHANNEL / 飞书</span><h2>在飞书里找到你的 Agent</h2></div><span class="im-state" role="status">检查连接…</span></div><p>扫码创建专属机器人，自动绑定扫码者的私聊通道。授权页面由飞书提供，无需在这里填写密码或复制密钥。</p><div class="im-actions"><button class="primary im-bind">飞书扫码绑定</button><button class="quiet im-refresh">刷新连接状态</button><button class="quiet im-disconnect" hidden>断开本地通道</button></div><p class="im-feedback" role="status"></p><div class="im-qr" hidden><img alt="使用飞书扫描此绑定二维码" width="280" height="280"><div><h3>用飞书扫一扫</h3><p>在手机上核对并确认应用和消息权限。仅申请机器人收发私聊消息，不申请云盘、通讯录全量或日历权限。</p><p class="im-expiry"></p><button class="quiet im-cancel">取消本次绑定</button></div></div><details><summary>绑定说明与手工备用方式</summary><p>首次扫码会在飞书创建“五简 JARVIS”应用。是否可用取决于组织权限和飞书开放范围。请以手机授权页列出的实际权限为准。</p><p>绑定完成后，向机器人发“帮助”测试私聊。只有长连接成功且真实消息能收发，才算通道可用。部分组织需管理员审批，或在开放平台确认长连接事件订阅。</p><p>一键流程不可用时，可继续使用项目里的“配置飞书机器人.command”。断开本地通道不会删除飞书应用或撤销平台授权，可在飞书开放平台另外管理。</p></details></section><div class="im-schedule"></div><section class="work-card"><h3>外观</h3><label class="settings-row">降低动态效果 <input type="checkbox" id="reduceMotion" ${document.body.classList.contains('reduced')?'checked':''}></label><label class="settings-row">专注决策模式 <input type="checkbox" id="focusSetting" ${document.body.classList.contains('focus')?'checked':''}></label></section>`;
const selector=host.querySelector('.voice-provider');selector.value=localStorage.getItem('jarvis-voice-provider')||'volc';selector.onchange=()=>localStorage.setItem('jarvis-voice-provider',selector.value);
const state=host.querySelector('.im-state'),feedback=host.querySelector('.im-feedback'),bind=host.querySelector('.im-bind'),disconnect=host.querySelector('.im-disconnect'),box=host.querySelector('.im-qr');let attempt=null,timer=null;
const clear=()=>{clearTimeout(timer);box.hidden=true;box.querySelector('img').removeAttribute('src')};
const refresh=async()=>{const s=await api('/api/feishu/status');if(!state.isConnected)return;state.textContent=s.configured?`已配置 · ${s.transport}${s.lastError?' · '+s.lastError:''}`:s.disabled?'已断开':'尚未绑定';disconnect.hidden=!s.configured;bind.textContent=s.configured?'重新扫码换绑':'飞书扫码绑定';};
const schedule=()=>{const p=host.querySelector('.im-schedule');p.replaceChildren();void mountFeishu(p)};
async function poll(){if(!state.isConnected)return;try{const s=await api('/api/feishu/bind/status',{id:attempt});if(!state.isConnected)return;
 if(s.status==='waiting'){const first=box.hidden;box.hidden=false;box.querySelector('img').src=s.qr;host.querySelector('.im-expiry').textContent=`剩余约 ${Math.max(0,Math.ceil((s.expiresAt-Date.now())/1000))} 秒`;feedback.textContent='等待你在飞书中扫码并确认';if(first)box.scrollIntoView({block:'center',behavior:'smooth'});}
 if(['preparing','saving'].includes(s.status))feedback.textContent=s.status==='saving'?'授权成功，正在保存并连接…':'正在向飞书申请二维码…';
 if(s.status==='bound'){clear();bind.disabled=false;feedback.textContent='已完成扫码绑定。请向飞书机器人发“帮助”验证收发，再开启定时报告。';await refresh();schedule();return}
 if(['failed','cancelled','expired'].includes(s.status)){clear();bind.disabled=false;feedback.textContent=s.error||'本次绑定已结束，可以重新扫码';return}
 timer=setTimeout(poll,2000);
 }catch(e){clear();bind.disabled=false;feedback.textContent=e.message}}
host.querySelector('.im-bind').onclick=async()=>{bind.disabled=true;clear();feedback.textContent='正在向飞书申请二维码…';try{const s=await api('/api/feishu/bind/start',{});attempt=s.id;void poll()}catch(e){feedback.textContent=e.message;bind.disabled=false}};
host.querySelector('.im-cancel').onclick=async()=>{try{await api('/api/feishu/bind/cancel',{id:attempt});clear();bind.disabled=false;feedback.textContent='本次绑定已取消'}catch(e){feedback.textContent=e.message}};
disconnect.onclick=async()=>{try{await api('/api/feishu/disconnect',{});clear();bind.disabled=false;feedback.textContent='本地通道及定时推送已停用。飞书应用仍保留。';await refresh();schedule()}catch(e){feedback.textContent=e.message}};
host.querySelector('.im-refresh').onclick=()=>refresh().catch(e=>feedback.textContent=e.message);
try{await refresh();const [model,voice,volc]=await Promise.all([api('/api/llm/status'),api('/api/live-voice/status'),api('/api/volc/status')]);if(!state.isConnected)return;host.querySelector('.model-state').textContent=model.configured?'DeepSeek · 已配置':'DeepSeek · 未配置';host.querySelector('.voice-state').textContent=`火山语音：${volc.configured?'已配置':'未配置'} · GPT-Live：${voice.configured?'已配置':'未配置'}`;schedule()}catch(e){feedback.textContent=e.message}
}
